import torch, torch.nn as nn, math, itertools
torch.manual_seed(0)
W = torch.load('/app/weights.pt', map_location='cpu')
D = torch.load('/app/dataset.pt', map_location='cpu')
src, tgt = D['src_sequences'], D['tgt_sequences']

class PE(nn.Module):
    def __init__(self, d=128):
        super().__init__()
        pe = torch.zeros(5000, d)
        pos = torch.arange(0, 5000, dtype=torch.float).unsqueeze(1)
        div = torch.exp(torch.arange(0, d, 2).float() * (-math.log(10000.0)/d))
        pe[:,0::2] = torch.sin(pos*div); pe[:,1::2] = torch.cos(pos*div)
        self.register_buffer('pe', pe.unsqueeze(0))
    def forward(self, x):
        return x + self.pe[:, :x.size(1), :]

def build(nhead, enc_layers=3, dec_layers=1):
    class M(nn.Module):
        def __init__(self):
            super().__init__()
            self.embedding = nn.Linear(64,128)
            self.pos_encoder = PE()
            self.transformer_encoder = nn.TransformerEncoder(
                nn.TransformerEncoderLayer(128, nhead, 256, batch_first=True), enc_layers)
            self.transformer_decoder = nn.TransformerDecoder(
                nn.TransformerDecoderLayer(128, nhead, 256, batch_first=True), dec_layers)
            self.output_layer = nn.Linear(128,64)
        def forward(self, s, t, scale=1.0, pe_tgt=True, causal=False):
            s = self.pos_encoder(self.embedding(s)*scale)
            t2 = self.embedding(t)*scale
            if pe_tgt: t2 = self.pos_encoder(t2)
            mem = self.transformer_encoder(s)
            mask = None
            if causal:
                n = t.size(1)
                mask = torch.triu(torch.ones(n,n,dtype=torch.bool), diagonal=1)
            o = self.transformer_decoder(t2, mem, tgt_mask=mask)
            return self.output_layer(o)
    return M()

def mse(m, **kw):
    m.eval()
    with torch.no_grad():
        out = m(src, tgt, **kw)
    return nn.functional.mse_loss(out, tgt).item()

for nhead in [8,4,2,1]:
    m = build(nhead)
    try:
        m.load_state_dict(W, strict=True)
    except Exception as e:
        print(nhead, 'load fail', e); continue
    for scale in [1.0, math.sqrt(128)]:
        for pe_tgt in [True, False]:
            for causal in [False, True]:
                print(f'nhead={nhead} scale={scale:.2f} pe_tgt={pe_tgt} causal={causal} mse={mse(m,scale=scale,pe_tgt=pe_tgt,causal=causal):.6f}')
